import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>BMP هي أقدم صيغة صور في ويندوز، وأيضًا الأكثر تبذيرًا. لقطة واحدة قد تزن 10 ميغابايتات.</p>\n<p>تحويل BMP إلى JPG هو أسرع طريقة لجعل صور ويندوز القديمة مفيدة مجددًا. النتيجة أصغر بعشرات المرات.</p>\n<p>يشرح هذا الدليل لماذا ملفات BMP كبيرة جدًا، وكيف يعمل التحويل، وما الإعدادات التي تستخدمها.</p>\n<h2 id=\"what-is-bmp\">ما BMP؟</h2>\n<p>ما BMP؟ صيغة صور قديمة من مايكروسوفت، تحفظ كل بكسل بدقة دون ضغط تقريبًا. كانت شائعة في ويندوز القديم.</p>\n<p>BMP بسيطة وعالمية في ويندوز، لكنها تهدر المساحة. ملف واحد قد يزن عشرات الميغابايتات.</p>\n<h2 id=\"why-bmp-is-huge\">لماذا ملفات BMP ضخمة جدًا؟</h2>\n<p>لماذا ملفات BMP ضخمة جدًا؟ لأن BMP غير مضغوطة تقريبًا: تحفظ كل بكسل بدقة دون تجاهل أي بيانات. JPG يتجاهل التفاصيل الدقيقة.</p>\n<p>صورة 1920 في 1080 كـBMP قد تزن 6 ميغابايتات، بينما JPG نفسها قد يزن 300 كيلوبايت. الفرق هائل.</p>\n<h2 id=\"how-conversion-works\">كيف يعمل تحويل BMP إلى JPG؟</h2>\n<p>كيف يعمل تحويل BMP إلى JPG؟ الأداة تقرأ بكسلات BMP، ثم تعيد ترميزها كـJPG مع ضغط مع فقدان. الصورة نفسها لا تتغير تقريبًا.</p>\n<p>التحويل سريع لأن BMP بسيطة. لا توجد تعقيدات مثل فك تشفير HEIC أو AVIF.</p>\n<h2 id=\"quality-settings\">إعدادات الجودة التي تعمل</h2>\n<p>إعدادات الجودة التي تعمل: جودة 90 مناسبة لمعظم الصور، و85 للمشاركة اليومية. جودة 95 للصور المهمة التي تحتاج إلى أقصى حدة.</p>\n<p>للقطات النصية، لا تنزل عن 85. النص يضبب بسرعة عند الجودة المنخفضة.</p>\n<h2 id=\"colour-depth\">ماذا يحدث لعمق اللون؟</h2>\n<p>ماذا يحدث لعمق اللون؟ BMP قد يكون بأعماق 1 بت أو 8 بت أو 24 بت. التحويل إلى JPG يحفظ الألوان بشكل صحيح في معظم الحالات.</p>\n<p>ملفات 1 بت (أبيض وأسود) تتحول بشكل ممتاز. ملفات 8 بت قد تفقد بعض دقة الألوان، لكن الفرق ضئيل عادة.</p>\n<h2 id=\"scanned-bmp-files\">لماذا ملفات BMP الممسوحة تضغط بشكل جيد جدًا؟</h2>\n<p>لماذا ملفات BMP الممسوحة تضغط بشكل جيد جدًا؟ لأن المستندات الممسوحة فيها مساحات بيضاء كبيرة وألوان قليلة. JPG يضغطها بكفاءة عالية.</p>\n<p>مستند ممسوح كـBMP بحجم 5 ميغابايت قد يصبح JPG بحجم 200 كيلوبايت. التوفير هائل للمستندات.</p>\n<h2 id=\"transparency-myth\">هل BMP فيه شفافية؟</h2>\n<p>هل BMP فيه شفافية؟ لا، BMP لا يدعم الشفافية في معظم الحالات. ملفات BMP معتمة، لذلك لا حاجة إلى التفكير في لون التعبئة.</p>\n<p>وللتحويل إلى صيغ أخرى، جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a>.</p>\n<h2 id=\"batch-converting\">تحويل مجلد مسح BMP بالجملة</h2>\n<p>لتحويل مجلد مسح BMP بالجملة، ارفع كل الملفات وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>راجع عينة من النتائج قبل الاعتماد على الدفعة كلها. إذا كان النص حادًا في العينة، فغالبًا بقية الملفات بنفس الجودة.</p>\n<h2 id=\"checking-quality\">مراجعة الجودة قبل التنزيل</h2>\n<p>مراجعة الجودة قبل التنزيل: قارن النتيجة بالأصل، وتأكد من أن النص حاد والألوان صحيحة ولا توجد تشوهات.</p>\n<p>كبّر الصورة وافحص التفاصيل الدقيقة. إذا بدت النتيجة جيدة مكبّرة، فهي جاهزة للاستخدام.</p>\n<h2 id=\"bmp-vs-png-decision\">من BMP إلى JPG أم من BMP إلى PNG؟</h2>\n<p>من BMP إلى JPG أم من BMP إلى PNG؟ اختر JPG للصور الفوتوغرافية واللقطات، وPNG للرسوم والنصوص التي تحتاج إلى حدة كاملة.</p>\n<p>إذا كانت الصورة تحتاج إلى تحرير متكرر، فاختر PNG. وإذا كانت للمشاركة، فJPG أفضل.</p>\n<h2 id=\"where-jpg-works\">أين يعمل JPG المحوّل؟</h2>\n<p>أين يعمل JPG المحوّل؟ في كل مكان: المتصفحات والبرامج والبوابات والطابعات. JPG هو العيار العالمي.</p>\n<p>إذا أرسلت JPG، فأنت متأكد من أنه سيُفتح. التوافق الكامل هو السبب الرئيسي للتحويل.</p>\n<h2 id=\"common-problems\">مشاكل شائعة وحلولها</h2>\n<p>مشاكل شائعة وحلولها: ملف يفشل في التحويل قد يكون تالفًا أو بصيغة BMP غير قياسية. تحقق من فتحه في عارض صور.</p>\n<p>إذا ظهرت الألوان غريبة بعد التحويل، فأعد التحويل من الملف الأصلي. ملفات BMP القديمة قد تستخدم لوحات ألوان غير عادية.</p>\n<h2 id=\"bmp-from-old-scanners\">ملفات BMP من ماسحات قديمة</h2>\n<p>ملفات BMP من ماسحات قديمة: الماسحات القديمة كانت تحفظ كـBMP افتراضيًا. حوّل هذه الملفات إلى JPG لتوفير المساحة وتسهيل المشاركة.</p>\n<p>للمستندات الممسوحة، استخدم جودة 90. النص يجب أن يبقى مقروءًا، والجودة العالية تضمن ذلك.</p>\n<h2 id=\"bmp-from-legacy-software\">ملفات BMP من برامج قديمة</h2>\n<p>ملفات BMP من برامج قديمة: البرامج القديمة كانت تحفظ الصور كـBMP. حوّلها إلى JPG قبل استخدامها في برامج حديثة.</p>\n<p>التحويل المسبق يمنع مشاكل التوافق. تحقق من أن كل صورة تفتح بشكل صحيح قبل الاعتماد عليها.</p>\n<h2 id=\"bmp-screenshots-games\">لقطات BMP من الألعاب</h2>\n<p>لقطات BMP من الألعاب: الألعاب القديمة كانت تحفظ اللقطات كـBMP. حوّلها إلى JPG للمشاركة والتخزين.</p>\n<p>للقطات الألعاب، استخدم جودة 90. التفاصيل الدقيقة في اللعبة تحتاج إلى جودة عالية.</p>\n<h2 id=\"bmp-from-cameras\">ملفات BMP من كاميرات رقمية</h2>\n<p>ملفات BMP من كاميرات رقمية: بعض الكاميرات القديمة كانت تحفظ كـBMP. حوّلها إلى JPG للمشاركة والتخزين.</p>\n<p>للصور الفوتوغرافية من الكاميرا، استخدم جودة 90. الصور تحتاج إلى أقصى جودة ممكنة.</p>\n<h2 id=\"archiving-converted-jpgs-bmp\">أرشفة ملفات JPG المحوّلة</h2>\n<p>لأرشفة ملفات JPG المحوّلة، احتفظ بالأصول BMP في مجلد منفصل. الأصل هو مصدر كل نسخة مستقبلية.</p>\n<p>وللخطوات العملية، استخدم <a href=\"/ar/tahwil-bmp-ila-jpg/\">محول BMP إلى JPG</a>، واقرأ <a href=\"/ar/blog/kayfiyya-tahwil-bmp-ila-jpg/\">كيفية تحويل BMP إلى JPG</a> و<a href=\"/ar/blog/bmp-vs-jpg-hajm-al-malaf/\">BMP مقابل JPG: حجم الملف</a>، أو جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> لصيغ أخرى.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"لماذا ملفات BMP ضخمة جدًا مقارنة بـJPG؟","answer":"لأن BMP غير مضغوط تقريبًا: يحفظ كل بكسل بدقة دون تجاهل أي بيانات. JPG يتجاهل التفاصيل الدقيقة، لذلك يكون أصغر بعشرات المرات."},{"question":"كم حجمًا يمكنني توفيره بتحويل BMP إلى JPG؟","answer":"التوفير هائل عادة: ملف BMP بحجم 10 ميغابايت قد يصبح JPG بحجم 500 كيلوبايت بجودة 90. التوفير يعتمد على محتوى الصورة."},{"question":"ما إعداد الجودة الذي يحافظ على لقطات BMP مقروءة؟","answer":"جودة 90 تحافظ على اللقطات مقروءة وواضحة. للقطات النصية لا تنزل عن 85، وإلا سيضبب النص."},{"question":"ما أكبر ملف BMP مقبول؟","answer":"الحد الأقصى يعتمد على متصفحك وذاكرته، لكن معظم الأدوات تقبل ملفات حتى 20 ميغابايت. الملفات الأكبر قد تحتاج إلى تقسيم."},{"question":"هل يمكن تحويل ملفات BMP القديمة بأعماق 1 بت أو 8 بت؟","answer":"نعم، يمكن تحويل ملفات BMP القديمة بأعماق 1 بت و8 بت. الأداة تتعرف على عمق اللون وتحوّله بشكل صحيح."},{"question":"متى يكون BMP إلى JPG أفضل من BMP إلى PNG؟","answer":"اختر JPG للصور الفوتوغرافية واللقطات، وPNG للرسوم والنصوص التي تحتاج إلى حدة كاملة دون فقدان."}];
